    SELECT portfolioref FROM annual_returns
    WHERE fundperf IS NOT NULL AND categoryperf IS NOT NULL
    GROUP BY portfolioref
    HAVING COUNT(*) >= 7
) sub;

SELECT COUNT(*) as cnt_8_no_null FROM (
    SELECT portfolioref FROM annual_returns
    WHERE fundperf IS NOT NULL AND categoryperf IS NOT NULL
    GROUP BY portfolioref
    HAVING COUNT(*) >= 8
) sub;

SELECT COUNT(*) as cnt_9_no_null FROM (
    SELECT portfolioref FROM annual_returns
    WHERE fundperf IS NOT NULL AND categoryperf IS NOT NULL
    GROUP BY portfolioref
    HAVING COUNT(*) >= 9
) sub;

