-- Check if portfolioref in annual_returns matches tickersym in funds
SELECT COUNT(DISTINCT ar.portfolioref) FROM annual_returns ar;
SELECT COUNT(DISTINCT f.tickersym) FROM funds f;
-- Check overlap
SELECT COUNT(*) FROM (
    SELECT DISTINCT ar.portfolioref 
    FROM annual_returns ar
    INTERSECT
    SELECT DISTINCT f.tickersym FROM funds f
) sub;

-- Check if sector_allocations.productlink matches funds.tickersym exactly
SELECT COUNT(*) FROM (
    SELECT sa.productlink 
    FROM sector_allocations sa
    JOIN funds f ON sa.productlink = f.tickersym
) sub;

-- Also check if there are any mismatches
SELECT sa.productlink FROM sector_allocations sa
LEFT JOIN funds f ON sa.productlink = f.tickersym
WHERE f.tickersym IS NULL LIMIT 5;
